CREATE DATABASE IF NOT EXISTS dnf_gm CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS dnf_gm.schema_versions (version int PRIMARY KEY, installed_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.admins (id int PRIMARY KEY, username varchar(64) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, totp_encrypted text NOT NULL, last_totp bigint NOT NULL DEFAULT -1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.recovery_codes (code_hash char(64) CHARACTER SET ascii PRIMARY KEY, used_at datetime NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.sessions (token_hash char(64) CHARACTER SET ascii PRIMARY KEY, csrf_encrypted text NOT NULL, created_at bigint NOT NULL, touched_at bigint NOT NULL, authenticated_at bigint NOT NULL, mode varchar(16) NOT NULL, KEY touched(touched_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.operations (operation_id char(32) CHARACTER SET ascii PRIMARY KEY, session_hash char(64) CHARACTER SET ascii NOT NULL, idempotency_key varchar(64) CHARACTER SET ascii COLLATE ascii_bin NULL UNIQUE, fingerprint char(64) CHARACTER SET ascii NOT NULL, action varchar(16) NOT NULL, request_json longtext NOT NULL, preview_json longtext NOT NULL, status varchar(24) NOT NULL, result_json longtext NULL, created_at bigint NOT NULL, expires_at bigint NOT NULL, KEY created(created_at), KEY session_created(session_hash,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.audit (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, operation_id varchar(64) CHARACTER SET ascii NOT NULL UNIQUE, actor varchar(64) NOT NULL, action varchar(32) NOT NULL, target_uid int NULL, reason varchar(200) NOT NULL, request_json longtext NOT NULL, result_json longtext NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY created(created_at), KEY target(target_uid)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.failures (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, operation_id varchar(64) CHARACTER SET ascii NOT NULL, error_type varchar(64) NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.gift_templates (id bigint unsigned AUTO_INCREMENT PRIMARY KEY, name varchar(80) NOT NULL, current_version int NOT NULL, enabled tinyint NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.gift_versions (template_id bigint unsigned NOT NULL, version int NOT NULL, payload_json longtext NOT NULL, created_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(template_id,version)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dnf_gm.owned_bans (uid int PRIMARY KEY, marker varchar(100) NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO dnf_gm.schema_versions(version) VALUES(1);
